const event = msg.payload;
const data = event.data || {};
const sender = data.from || {};
const cell = (value) => '"' + String(value === undefined || value === null ? '' : value).replace(/"/g, '""') + '"';
msg.payload = [
    cell(event.created_at),
    cell(event.number_alias),
    cell(sender.number),
    cell(sender.name),
    cell(data.content_type),
    cell(data.preview),
].join(',');
return msg;
